# Reciprocal rank fusion: combine rankings, not incomparable raw scores.
rankings = [["doc-a", "doc-b"], ["doc-b", "doc-c"]]
fused = {}
for ranking in rankings:
    for rank, doc in enumerate(ranking, start=1):
        fused[doc] = fused.get(doc, 0) + 1 / (60 + rank)
ordered = sorted(fused, key=lambda doc: (-fused[doc], doc))
print(ordered)
# Retrieve only authorized documents before fusion/reranking.
allowed = {"doc-a", "doc-b"}
print([doc for doc in ordered if doc in allowed])

